/**
 * Shared hover state for coordinating hover / tooltip interactions across
 * multiple chart instances.
 *
 * Each chart instance keeps its own local hover state. When `syncHover` is
 * enabled the hover state is promoted to a module-level global store so every
 * instance reflects the same hovered index/chart. The `syncHover` and
 * `syncTooltip` preferences are persisted to `localStorage` so they survive
 * page reloads.
 */

export const HOVER_SYNC_STORAGE_KEY = 'supabase-chart-hover-sync-enabled'
export const TOOLTIP_SYNC_STORAGE_KEY = 'supabase-chart-tooltip-sync-enabled'

export interface ChartHoverState {
  /** Index of the hovered data point, or null when nothing is hovered. */
  hoveredIndex: number | null
  /** Id of the chart that owns the current hover, or null. */
  hoveredChart: string | null
  /** True when a data point is currently hovered (index is non-null). */
  isHovered: boolean
  /** True only for the instance whose `chartId` matches `hoveredChart`. */
  isCurrentChart: boolean
  /** Whether hover state is synchronized across all chart instances. */
  syncHover: boolean
  /** Whether tooltip state is synchronized across all chart instances. */
  syncTooltip: boolean
  /** Set the hovered index for this instance. */
  setHover: (index: number | null) => void
  /** Clear the hover state for this instance. */
  clearHover: () => void
  /** Enable/disable hover synchronization for every instance. */
  setSyncHover: (enabled: boolean) => void
  /** Enable/disable tooltip synchronization for every instance. */
  setSyncTooltip: (enabled: boolean) => void
}

interface GlobalHoverState {
  hoveredIndex: number | null
  hoveredChart: string | null
  syncHover: boolean
  syncTooltip: boolean
}

const getDefaultGlobalState = (): GlobalHoverState => ({
  hoveredIndex: null,
  hoveredChart: null,
  syncHover: false,
  syncTooltip: false,
})

let globalState: GlobalHoverState = getDefaultGlobalState()
const subscribers = new Set<() => void>()

const notify = () => {
  subscribers.forEach((callback) => callback())
}

/**
 * Read a boolean sync preference from localStorage. Defaults to `false` when
 * the key is absent, and defaults to `false` while emitting a console warning
 * when the stored value is corrupted or cannot be JSON-parsed.
 */
const readSyncSetting = (key: string): boolean => {
  try {
    if (typeof localStorage === 'undefined') return false

    const raw = localStorage.getItem(key)
    if (raw === null || raw === undefined) return false

    return JSON.parse(raw) === true
  } catch (error) {
    console.warn('Failed to read chart hover sync setting from localStorage:', error)
    return false
  }
}

/**
 * Persist a boolean sync preference to localStorage. Any failure is swallowed
 * so the in-memory state can still be updated; a warning is logged instead.
 */
const writeSyncSetting = (key: string, value: boolean) => {
  try {
    if (typeof localStorage === 'undefined') return
    localStorage.setItem(key, JSON.stringify(value))
  } catch (error) {
    console.warn('Failed to save chart hover sync setting to localStorage:', error)
  }
}

/**
 * Re-hydrate the global sync preferences from localStorage and reset the
 * transient hover state. Called when the first instance mounts so preferences
 * always reflect what is currently persisted (e.g. after a page reload).
 */
const initializeFromStorage = () => {
  globalState = {
    hoveredIndex: null,
    hoveredChart: null,
    syncHover: readSyncSetting(HOVER_SYNC_STORAGE_KEY),
    syncTooltip: readSyncSetting(TOOLTIP_SYNC_STORAGE_KEY),
  }
}

// Initialise once at module load so the first synchronous read is correct.
initializeFromStorage()

export function useChartHoverState(chartId: string): ChartHoverState {
  // Local (non-synchronized) hover state for this instance.
  const [localHover, setLocalHover] = useState<{
    hoveredIndex: number | null
    hoveredChart: string | null
  }>({ hoveredIndex: null, hoveredChart: null })

  // Snapshot of the global store used to trigger re-renders on change.
  const [snapshot, setSnapshot] = useState<GlobalHoverState>(() => ({ ...globalState }))

  useEffect(() => {
    // When no instances are currently subscribed, refresh preferences from
    // storage so a freshly mounted set of charts reflects persisted settings.
    if (subscribers.size === 0) {
      initializeFromStorage()
    }

    const callback = () => setSnapshot({ ...globalState })
    subscribers.add(callback)

    // Ensure this instance's snapshot is in sync after any (re)initialization.
    setSnapshot({ ...globalState })

    return () => {
      subscribers.delete(callback)
    }
  }, [])

  const setHover = useCallback(
    (index: number | null) => {
      if (globalState.syncHover) {
        globalState = { ...globalState, hoveredIndex: index, hoveredChart: chartId }
        notify()
      } else {
        setLocalHover({ hoveredIndex: index, hoveredChart: chartId })
      }
    },
    [chartId]
  )

  const clearHover = useCallback(() => {
    if (globalState.syncHover) {
      globalState = { ...globalState, hoveredIndex: null, hoveredChart: null }
      notify()
    } else {
      setLocalHover({ hoveredIndex: null, hoveredChart: null })
    }
  }, [])

  const setSyncHover = useCallback((enabled: boolean) => {
    // No-op if the requested state already matches the current state.
    if (globalState.syncHover === enabled) return

    // Disabling hover sync also disables tooltip sync.
    const nextSyncTooltip = enabled ? globalState.syncTooltip : false

    globalState = { ...globalState, syncHover: enabled, syncTooltip: nextSyncTooltip }

    writeSyncSetting(HOVER_SYNC_STORAGE_KEY, enabled)
    if (!enabled) {
      writeSyncSetting(TOOLTIP_SYNC_STORAGE_KEY, false)
    }

    notify()
  }, [])

  const setSyncTooltip = useCallback((enabled: boolean) => {
    // Enabling tooltip sync requires hover sync to be enabled as well.
    const nextSyncHover = enabled ? true : globalState.syncHover

    // No-op if nothing would change.
    if (globalState.syncTooltip === enabled && globalState.syncHover === nextSyncHover) return

    globalState = { ...globalState, syncTooltip: enabled, syncHover: nextSyncHover }

    writeSyncSetting(TOOLTIP_SYNC_STORAGE_KEY, enabled)
    writeSyncSetting(HOVER_SYNC_STORAGE_KEY, nextSyncHover)

    notify()
  }, [])

  const syncHover = snapshot.syncHover
  const syncTooltip = snapshot.syncTooltip

  // Synchronized instances read from the global store; otherwise from local state.
  const hoveredIndex = syncHover ? snapshot.hoveredIndex : localHover.hoveredIndex
  const hoveredChart = syncHover ? snapshot.hoveredChart : localHover.hoveredChart

  return {
    hoveredIndex,
    hoveredChart,
    isHovered: hoveredIndex !== null,
    isCurrentChart: hoveredChart === chartId,
    syncHover,
    syncTooltip,
    setHover,
    clearHover,
    setSyncHover,
    setSyncTooltip,
  }
}

/**
 * Reset all shared hover state back to defaults. Primarily useful for tests to
 * guarantee isolation between cases.
 */
export function resetChartHoverState() {
  globalState = getDefaultGlobalState()
  notify()
}
