import { describe, it, expect, beforeEach, vi } from 'vitest'
import {
  useChartHoverState,
  resetChartHoverState,
  HOVER_SYNC_STORAGE_KEY,
  TOOLTIP_SYNC_STORAGE_KEY,
} from './useChartHoverState'

describe('useChartHoverState', () => {
  beforeEach(() => {
    localStorage.clear()
    resetChartHoverState()
  })

  it('defaults', () => {
    const { result } = renderHook(() => useChartHoverState('c1'))
    expect(result.current).toMatchObject({
      hoveredIndex: null,
      hoveredChart: null,
      isHovered: false,
      isCurrentChart: false,
      syncHover: false,
      syncTooltip: false,
    })
  })

  it('local hover only affects self', () => {
    const a = renderHook(() => useChartHoverState('a'))
    const b = renderHook(() => useChartHoverState('b'))
    act(() => a.result.current.setHover(3))
    expect(a.result.current.hoveredIndex).toBe(3)
    expect(a.result.current.isHovered).toBe(true)
    expect(a.result.current.isCurrentChart).toBe(true)
    expect(b.result.current.hoveredIndex).toBe(null)
    expect(b.result.current.isCurrentChart).toBe(false)
  })

  it('synced hover propagates; isCurrentChart only for caller', () => {
    const a = renderHook(() => useChartHoverState('a'))
    const b = renderHook(() => useChartHoverState('b'))
    act(() => a.result.current.setSyncHover(true))
    act(() => a.result.current.setHover(5))
    expect(a.result.current.hoveredIndex).toBe(5)
    expect(b.result.current.hoveredIndex).toBe(5)
    expect(a.result.current.isHovered).toBe(true)
    expect(b.result.current.isHovered).toBe(true)
    expect(a.result.current.isCurrentChart).toBe(true)
    expect(b.result.current.isCurrentChart).toBe(false)
    act(() => b.result.current.clearHover())
    expect(a.result.current.hoveredIndex).toBe(null)
    expect(b.result.current.hoveredIndex).toBe(null)
  })

  it('reads sync prefs from localStorage', () => {
    localStorage.setItem(HOVER_SYNC_STORAGE_KEY, 'true')
    const { result } = renderHook(() => useChartHoverState('a'))
    expect(result.current.syncHover).toBe(true)
  })

  it('corrupted localStorage defaults to false + warns', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    localStorage.setItem(HOVER_SYNC_STORAGE_KEY, 'not-json{')
    const { result } = renderHook(() => useChartHoverState('a'))
    expect(result.current.syncHover).toBe(false)
    expect(warn).toHaveBeenCalled()
    warn.mockRestore()
  })

  it('disabling syncHover disables syncTooltip and persists', () => {
    const a = renderHook(() => useChartHoverState('a'))
    act(() => a.result.current.setSyncTooltip(true))
    expect(a.result.current.syncTooltip).toBe(true)
    expect(a.result.current.syncHover).toBe(true)
    expect(localStorage.getItem(TOOLTIP_SYNC_STORAGE_KEY)).toBe('true')
    expect(localStorage.getItem(HOVER_SYNC_STORAGE_KEY)).toBe('true')
    act(() => a.result.current.setSyncHover(false))
    expect(a.result.current.syncHover).toBe(false)
    expect(a.result.current.syncTooltip).toBe(false)
    expect(localStorage.getItem(TOOLTIP_SYNC_STORAGE_KEY)).toBe('false')
  })

  it('setSyncHover no-op when unchanged', () => {
    const a = renderHook(() => useChartHoverState('a'))
    const spy = vi.spyOn(Storage.prototype, 'setItem')
    act(() => a.result.current.setSyncHover(false))
    expect(spy).not.toHaveBeenCalled()
    spy.mockRestore()
  })

  it('rapid sequential calls reflect final state', () => {
    const a = renderHook(() => useChartHoverState('a'))
    act(() => {
      a.result.current.setHover(1)
      a.result.current.setHover(2)
      a.result.current.clearHover()
      a.result.current.setHover(9)
    })
    expect(a.result.current.hoveredIndex).toBe(9)
  })
})
